"""Generic payload verification for mp.*.example.* claims.

These checks are intentionally data-oriented: if a claim carries a JSON snippet
example, the snippet must match actual corpus data.

This module intentionally implements a small custom JSON pattern-matching
language. We considered off-the-shelf approaches (for example JSON Schema and
JSONPath/JMESPath), but they were not a clean fit for this use case, which
needs all of the following at once: exact-key object matching, ordered list
matching, and recursive "match anywhere in subtree" search over JSON-like
nodes.

Snippet wildcard semantics are encoded explicitly with strict-JSON tokens:
- {"__verify_mp_any_dict__": true} as a dict wildcard
- {"__verify_mp_any_list__": true} as a list wildcard
- {"__verify_mp_any_string_dict_or_list__": true} as a string/dict/list wildcard
- {"__verify_mp_wildcard_string__": "prefix ... suffix"} as a wildcard string
"""

import json

from mb_author.claim import ClaimRecord
from verify_mp.corpus import Context
from verify_mp.pattern_match import match_pattern


def is_example_claim(record: ClaimRecord) -> bool:
    """Return whether this claim id is in the explicit example namespace."""
    return ".example." in record.id


def verify_example_payload(record: ClaimRecord, ctx: Context) -> None:
    """Assert that an example claim payload matches at least one corpus node."""
    pattern = _normalize_payload(record)
    roots = _roots_for_subject(record, ctx)
    for root in roots:
        if _contains_pattern(root, pattern):
            return
    assert False, f"example payload pattern not found in corpus: {record.id}"


def _normalize_payload(record: ClaimRecord):
    """Parse strict-JSON snippet payloads."""
    payload = record.payload
    if not isinstance(payload, str):
        return payload

    text = payload.strip()
    if not text:
        return payload

    if not text.startswith("{") and not text.startswith("["):
        return payload

    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        assert False, f"claim {record.id}: payload must be strict JSON: {exc}"


def _roots_for_subject(record: ClaimRecord, ctx: Context) -> list:
    """Return corpus roots to search based on claim subject."""
    if record.subject == "mp:plus":
        return ctx.corpus.files
    if record.subject == "mp:plain":
        return ctx.corpus_plain.files
    assert record.subject == "mp:both"
    return [*ctx.corpus.files, *ctx.corpus_plain.files]


def _contains_pattern(node, pattern) -> bool:
    """Return whether pattern matches node itself or any descendant node."""
    if match_pattern(pattern, node):
        return True
    if isinstance(node, dict):
        return any(_contains_pattern(value, pattern) for value in node.values())
    if isinstance(node, list):
        return any(_contains_pattern(item, pattern) for item in node)
    return False
